--radius-lg: 12px;     /* 모달·카운터 */
--radius-xl: 24px;     /* 태그·스위치 알약형 */
--radius-full: 9999px; /* 아바타 */
--shadow-none: none;
--shadow-sm: 0 0 1px 0 rgba(25,27,35,.16), 0 1px 2px 0 rgba(25,27,35,.12); /* 카드 기본 */
--shadow-md: 0 1px 12px 0 rgba(25,27,35,.15);   /* 드롭다운·팝오버 */
--shadow-lg: 0 3px 8px 0 rgba(25,27,35,.2);     /* 모달 */
--shadow-xl: 3px 3px 30px 0 rgba(25,27,35,.15); /* 카드 hover·끌어 옮기는 위젯 */
--duration-fast: 100ms;   /* extra-fast · 스위치 */
--duration-base: 200ms;   /* control·popper·modal·accordion 공통 */
--duration-slow: 400ms;
--ease-out: cubic-bezier(0.2, 0, 0, 1);   /* (추정) */
--ease-in-out: ease-in-out;               /* (추정) */
}
:root {
  /* Primary - Semrush Orange (다크에서도 동일) */
  --color-primary-50:  #3A1A0C;  /* 경고 옅은 면 다크 보정 (추정) */
  --color-primary-100: #551200;
  --color-primary-200: #8B1500;
  --color-primary-300: #C33909;
  --color-primary-400: #FF7849;  /* 보간값 (추정) */
  --color-primary-500: #FF642D;  /* 기본 — 브랜드 CTA (control-primary-brand) */
  --color-primary-600: #C33909;  /* hover (다크 control-primary-brand-hover) */
  --color-primary-700: #C33909;  /* active (다크 테마는 hover 와 같은 값) */
  --color-primary-800: #FF8C43;
  --color-primary-900: #FFB26E;

  /* Secondary - Info Blue */
  --color-secondary-500: #008FF8;  /* control-primary-info (다크 동일) */
  --color-secondary-600: #2BB3FF;
  --color-secondary-700: #8ECDFF;
  --color-header-bg:     #1D113E;
  --color-header-border: #382E5E;
  --color-nav-active-bg: #382E5E;  /* 다크 사이드 내비 활성 (추정) */
  --color-nav-text:      #BCB1E9;  /* (추정) */
  --color-nav-text-active: #E2DDFF;
  --color-brand-lavender: #C190FF;
  --color-brand-aqua:     #18F0BF;
  --color-brand-mint:     #DCEEEB;
  --color-brand-black:    #181E15;

  /* Neutral (다크에서 위계 반전) */
  --color-neutral-0:    #161925;
  --color-neutral-50:   #1E2231;
  --color-neutral-100:  #2D303E;
  --color-neutral-200:  #484A54;
  --color-neutral-300:  #6C6E79;
  --color-neutral-400:  #8A8E9B;
  --color-neutral-500:  #A9ABB6;
  --color-neutral-600:  #C4C7CF;
  --color-neutral-700:  #E0E1E9;
  --color-neutral-800:  #F4F5F9;
  --color-neutral-1000: #FFFFFF;

  /* Semantic (글자는 다크 테마 실측, 배경은 보정 추정) */
  --color-success-bg: #0F3A33;
  --color-success-fg: #44D1A4;
  --color-warning-bg: #3A1A0C;
  --color-warning-fg: #FF8C43;
  --color-error-bg:   #3F1520;
  --color-error-fg:   #FF9B94;
  --color-info-bg:    #34445A;   /* bg-secondary-info 실측 */
  --color-info-fg:    #8ECDFF;

  /* Surface */
  --bg-base:     #161925;   /* 페이지 (추정) */
  --bg-subtle:   #2D303E;   /* bg-secondary-neutral 실측 */
  --bg-elevated: #1E2231;   /* 카드 (bg-primary-neutral 실측) */
  --bg-overlay:  #2D303E;
  --bg-invert:   #191B23;

  /* Text */
  --text-primary:    #F4F5F9;
  --text-secondary:  #A9ABB6;
  --text-tertiary:   #8A8E9B;
  --text-on-primary: #FFFFFF;
  --text-disabled:   #6C6E79;
  --text-link:       #8ECDFF;

  /* Border */
  --border-default: #484A54;
  --border-subtle:  #2D303E;
  --border-strong:  #6C6E79;
  --border-focus:   rgba(0, 143, 248, 0.5);
}

