  /* Semantic (실측) */
  --color-success-bg: #DBFEE8;
  --color-success-fg: #007C65;
  --color-warning-bg: #FFF3D9;
  --color-warning-fg: #C33909;
  --color-error-bg:   #FFF0F7;
  --color-error-fg:   #D1002F;
  --color-info-bg:    #E9F7FF;
  --color-info-fg:    #006DCA;

  /* Surface */
