  --bg-subtle:   #F4F5F9;   /* 표 머리·섹션 */
  --bg-elevated: #FFFFFF;   /* 카드·위젯 (bg-primary-neutral) */
  --bg-overlay:  #FFFFFF;   /* 드롭다운·모달 */
