  --text-primary:    #191B23;
  --text-secondary:  #6C6E79;
  --text-tertiary:   #8A8E9B;
  --text-on-primary: #FFFFFF;
  --text-disabled:   #A9ABB6;   /* 실제로는 컴포넌트 전체 opacity .3 로 비활성 처리 */
